  {
   "type": "code",
   "caption": "My A* implementation",
   "lang": "py",
   "file": "search.py",
   "lines": [
    "    <span class=\"tok-n\">goal_list_of_actions</span> <span class=\"tok-o\">=</span> <span class=\"tok-p\">[</span><span class=\"tok-p\">]</span>",
    "    <span class=\"tok-n\">start</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">problem</span><span class=\"tok-o\">.</span><span class=\"tok-n\">getStartState</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "",
    "    <span class=\"tok-k\">if</span> <span class=\"tok-n\">problem</span><span class=\"tok-o\">.</span><span class=\"tok-n\">isGoalState</span><span class=\"tok-p\">(</span><span class=\"tok-n\">start</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "        <span class=\"tok-k\">return</span> <span class=\"tok-n\">goal_list_of_actions</span>",
    "",
    "    <span class=\"tok-n\">visited</span> <span class=\"tok-o\">=</span> <span class=\"tok-nb\">set</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-n\">priority_queue</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">util</span><span class=\"tok-o\">.</span><span class=\"tok-n\">PriorityQueue</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-n\">priority_queue</span><span class=\"tok-o\">.</span><span class=\"tok-n\">push</span><span class=\"tok-p\">(</span><span class=\"tok-n\">start</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">heuristic</span><span class=\"tok-p\">(</span><span class=\"tok-n\">start</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">problem</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-c1\"># (list of actions, cost) to reach that state from the start</span>",
    "    <span class=\"tok-n\">lists_of_actions</span> <span class=\"tok-o\">=</span> <span class=\"tok-p\">{</span><span class=\"tok-n\">start</span><span class=\"tok-p\">:</span> <span class=\"tok-p\">(</span><span class=\"tok-p\">[</span><span class=\"tok-p\">]</span><span class=\"tok-p\">,</span> <span class=\"tok-mi\">0</span><span class=\"tok-p\">)</span><span class=\"tok-p\">}</span>",
    "",
    "    <span class=\"tok-k\">while</span> <span class=\"tok-ow\">not</span> <span class=\"tok-n\">priority_queue</span><span class=\"tok-o\">.</span><span class=\"tok-n\">isEmpty</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span> <span class=\"tok-ow\">and</span> <span class=\"tok-ow\">not</span> <span class=\"tok-n\">goal_list_of_actions</span><span class=\"tok-p\">:</span>",
    "        <span class=\"tok-n\">current_state</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">priority_queue</span><span class=\"tok-o\">.</span><span class=\"tok-n\">pop</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "",
    "        <span class=\"tok-k\">if</span> <span class=\"tok-n\">current_state</span> <span class=\"tok-ow\">not</span> <span class=\"tok-ow\">in</span> <span class=\"tok-n\">visited</span><span class=\"tok-p\">:</span>",
    "            <span class=\"tok-n\">visited</span><span class=\"tok-o\">.</span><span class=\"tok-n\">add</span><span class=\"tok-p\">(</span><span class=\"tok-n\">current_state</span><span class=\"tok-p\">)</span>",
    "            <span class=\"tok-n\">current_cost</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">lists_of_actions</span><span class=\"tok-p\">[</span><span class=\"tok-n\">current_state</span><span class=\"tok-p\">]</span><span class=\"tok-p\">[</span><span class=\"tok-mi\">1</span><span class=\"tok-p\">]</span>",
    "",
    "            <span class=\"tok-k\">if</span> <span class=\"tok-n\">problem</span><span class=\"tok-o\">.</span><span class=\"tok-n\">isGoalState</span><span class=\"tok-p\">(</span><span class=\"tok-n\">current_state</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "                <span class=\"tok-n\">goal_list_of_actions</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">lists_of_actions</span><span class=\"tok-p\">[</span><span class=\"tok-n\">current_state</span><span class=\"tok-p\">]</span><span class=\"tok-p\">[</span><span class=\"tok-mi\">0</span><span class=\"tok-p\">]</span>",
    "            ",
    "            <span class=\"tok-k\">else</span><span class=\"tok-p\">:</span>",
    "                <span class=\"tok-k\">for</span> <span class=\"tok-n\">position</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">direction</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">cost</span> <span class=\"tok-ow\">in</span> <span class=\"tok-n\">problem</span><span class=\"tok-o\">.</span><span class=\"tok-n\">getSuccessors</span><span class=\"tok-p\">(</span><span class=\"tok-n\">current_state</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "                    <span class=\"tok-n\">cost_to_successor</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">current_cost</span> <span class=\"tok-o\">+</span> <span class=\"tok-n\">cost</span>",
    "",
    "                    <span class=\"tok-k\">if</span> <span class=\"tok-p\">(</span><span class=\"tok-n\">position</span> <span class=\"tok-ow\">not</span> <span class=\"tok-ow\">in</span> <span class=\"tok-n\">lists_of_actions</span><span class=\"tok-p\">)</span> <span class=\"tok-ow\">or</span> <span class=\"tok-p\">(</span><span class=\"tok-n\">cost_to_successor</span> <span class=\"tok-o\">&lt;</span> <span class=\"tok-n\">lists_of_actions</span><span class=\"tok-p\">[</span><span class=\"tok-n\">position</span><span class=\"tok-p\">]</span><span class=\"tok-p\">[</span><span class=\"tok-mi\">1</span><span class=\"tok-p\">]</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "                        <span class=\"tok-n\">priority_queue</span><span class=\"tok-o\">.</span><span class=\"tok-n\">update</span><span class=\"tok-p\">(</span><span class=\"tok-n\">position</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">cost_to_successor</span> <span class=\"tok-o\">+</span> <span class=\"tok-n\">heuristic</span><span class=\"tok-p\">(</span><span class=\"tok-n\">position</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">problem</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span>",
    "                        <span class=\"tok-n\">lists_of_actions</span><span class=\"tok-p\">[</span><span class=\"tok-n\">position</span><span class=\"tok-p\">]</span> <span class=\"tok-o\">=</span> <span class=\"tok-p\">(</span><span class=\"tok-n\">lists_of_actions</span><span class=\"tok-p\">[</span><span class=\"tok-n\">current_state</span><span class=\"tok-p\">]</span><span class=\"tok-p\">[</span><span class=\"tok-mi\">0</span><span class=\"tok-p\">]</span> <span class=\"tok-o\">+</span> <span class=\"tok-p\">[</span><span class=\"tok-n\">direction</span><span class=\"tok-p\">]</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">cost_to_successor</span><span class=\"tok-p\">)</span>",
    "",
    "    <span class=\"tok-k\">return</span> <span class=\"tok-n\">goal_list_of_actions</span>",
    "",
    "<span class=\"tok-c1\"># Abbreviations</span>",
    "<span class=\"tok-n\">bfs</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">breadthFirstSearch</span>",
    "<span class=\"tok-n\">dfs</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">depthFirstSearch</span>",
    "<span class=\"tok-n\">astar</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">aStarSearch</span>",
    "<span class=\"tok-n\">ucs</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">uniformCostSearch</span>"
   ],
   "start": 216
  }
