    "<span class=\"tok-w\">    </span><span class=\"tok-n\">top_pct</span><span class=\"tok-w\"> </span><span class=\"tok-o\">&lt;-</span><span class=\"tok-w\"> </span><span class=\"tok-nf\">max</span><span class=\"tok-p\">(</span><span class=\"tok-n\">scores_tbl</span><span class=\"tok-o\">$</span><span class=\"tok-n\">Percent</span><span class=\"tok-p\">)</span>",
