    "<span class=\"tok-w\">  </span><span class=\"tok-p\">}</span>",
    "<span class=\"tok-w\">  </span><span class=\"tok-n\">recommendation</span><span class=\"tok-w\"> </span><span class=\"tok-o\">&lt;-</span><span class=\"tok-w\"> </span><span class=\"tok-n\">winners</span><span class=\"tok-o\">$</span><span class=\"tok-n\">Drug</span>",
