    "",
    "<span class=\"tok-k\">def</span><span class=\"tok-w\"> </span><span class=\"tok-nf\">convert_to_watt</span><span class=\"tok-p\">(</span><span class=\"tok-n\">x</span><span class=\"tok-p\">:</span> <span class=\"tok-nb\">float</span><span class=\"tok-p\">)</span> <span class=\"tok-o\">-</span><span class=\"tok-o\">&gt;</span> <span class=\"tok-nb\">float</span><span class=\"tok-p\">:</span>",
