    "<span class=\"tok-w\">                </span><span class=\"tok-p\">)</span>",
    "<span class=\"tok-w\">                </span><span class=\"tok-k\">if</span><span class=\"tok-w\"> </span><span class=\"tok-p\">(</span><span class=\"tok-n\">gpsTrack</span><span class=\"tok-w\"> </span><span class=\"tok-o\">!</span><span class=\"tok-o\">=</span><span class=\"tok-w\"> </span><span class=\"tok-kc\">null</span><span class=\"tok-p\">)</span><span class=\"tok-w\"> </span><span class=\"tok-p\">{</span>",
