    "",
    "<span class=\"tok-w\">        </span><span class=\"tok-n\">fusedLocationClient</span><span class=\"tok-p\">.</span><span class=\"tok-na\">lastLocation</span><span class=\"tok-p\">.</span><span class=\"tok-na\">addOnSuccessListener</span><span class=\"tok-w\"> </span><span class=\"tok-p\">{</span><span class=\"tok-w\"> </span><span class=\"tok-n\">location</span><span class=\"tok-p\">:</span><span class=\"tok-w\"> </span><span class=\"tok-n\">Location?</span><span class=\"tok-w\"> </span><span class=\"tok-o\">-</span><span class=\"tok-o\">&gt;</span>",
