    "<span class=\"tok-w\">                        </span><span class=\"tok-n\">zoomLevel</span><span class=\"tok-p\">,</span>",
    "<span class=\"tok-w\">                        </span><span class=\"tok-n\">tiltLevel</span><span class=\"tok-p\">,</span>",
