    "",
    "<span class=\"tok-w\">        </span><span class=\"tok-kd\">val</span><span class=\"tok-w\"> </span><span class=\"tok-nv\">polylineOptions</span><span class=\"tok-w\"> </span><span class=\"tok-o\">=</span><span class=\"tok-w\"> </span><span class=\"tok-n\">PolylineOptions</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
