   "lines": [
    "<span class=\"tok-k\">def</span><span class=\"tok-w\"> </span><span class=\"tok-nf\">build_custom_cnn_model</span><span class=\"tok-p\">(</span><span class=\"tok-n\">input_shape</span><span class=\"tok-p\">:</span> <span class=\"tok-nb\">tuple</span><span class=\"tok-p\">[</span><span class=\"tok-nb\">int</span><span class=\"tok-p\">,</span> <span class=\"tok-nb\">int</span><span class=\"tok-p\">,</span> <span class=\"tok-nb\">int</span><span class=\"tok-p\">]</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">num_classes</span><span class=\"tok-p\">:</span> <span class=\"tok-nb\">int</span><span class=\"tok-p\">)</span> <span class=\"tok-o\">-</span><span class=\"tok-o\">&gt;</span> <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">models</span><span class=\"tok-o\">.</span><span class=\"tok-n\">Sequential</span><span class=\"tok-p\">:</span>",
    "    <span class=\"tok-n\">model</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">models</span><span class=\"tok-o\">.</span><span class=\"tok-n\">Sequential</span><span class=\"tok-p\">(</span><span class=\"tok-p\">[</span>",
    "        <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">layers</span><span class=\"tok-o\">.</span><span class=\"tok-n\">Conv2D</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">32</span><span class=\"tok-p\">,</span> <span class=\"tok-p\">(</span><span class=\"tok-mi\">3</span><span class=\"tok-p\">,</span> <span class=\"tok-mi\">3</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">activation</span><span class=\"tok-o\">=</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">relu</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">input_shape</span><span class=\"tok-o\">=</span><span class=\"tok-n\">input_shape</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span>",
    "        <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">layers</span><span class=\"tok-o\">.</span><span class=\"tok-n\">MaxPooling2D</span><span class=\"tok-p\">(</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">2</span><span class=\"tok-p\">,</span> <span class=\"tok-mi\">2</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span>",
    "        <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">layers</span><span class=\"tok-o\">.</span><span class=\"tok-n\">Conv2D</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">64</span><span class=\"tok-p\">,</span> <span class=\"tok-p\">(</span><span class=\"tok-mi\">3</span><span class=\"tok-p\">,</span> <span class=\"tok-mi\">3</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">activation</span><span class=\"tok-o\">=</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">relu</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span>",
    "        <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">layers</span><span class=\"tok-o\">.</span><span class=\"tok-n\">MaxPooling2D</span><span class=\"tok-p\">(</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">2</span><span class=\"tok-p\">,</span> <span class=\"tok-mi\">2</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span>",
    "        <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">layers</span><span class=\"tok-o\">.</span><span class=\"tok-n\">Conv2D</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">64</span><span class=\"tok-p\">,</span> <span class=\"tok-p\">(</span><span class=\"tok-mi\">3</span><span class=\"tok-p\">,</span> <span class=\"tok-mi\">3</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">activation</span><span class=\"tok-o\">=</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">relu</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span>",
    "        <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">layers</span><span class=\"tok-o\">.</span><span class=\"tok-n\">Flatten</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span>",
    "        <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">layers</span><span class=\"tok-o\">.</span><span class=\"tok-n\">Dense</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">64</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">activation</span><span class=\"tok-o\">=</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">relu</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span>",
    "        <span class=\"tok-n\">k</span><span class=\"tok-o\">.</span><span class=\"tok-n\">layers</span><span class=\"tok-o\">.</span><span class=\"tok-n\">Dense</span><span class=\"tok-p\">(</span><span class=\"tok-n\">num_classes</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">activation</span><span class=\"tok-o\">=</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">softmax</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-p\">]</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-n\">model</span><span class=\"tok-o\">.</span><span class=\"tok-n\">summary</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-k\">return</span> <span class=\"tok-n\">model</span>"
   ],
