    "<span class=\"tok-w\">            </span><span class=\"tok-n\">zone</span><span class=\"tok-o\">-</span><span class=\"tok-o\">&gt;</span><span class=\"tok-n\">tab</span><span class=\"tok-p\">[</span><span class=\"tok-n\">i</span><span class=\"tok-o\">+</span><span class=\"tok-mi\">1</span><span class=\"tok-p\">]</span><span class=\"tok-w\"> </span><span class=\"tok-o\">=</span><span class=\"tok-w\"> </span><span class=\"tok-n\">zone</span><span class=\"tok-o\">-</span><span class=\"tok-o\">&gt;</span><span class=\"tok-n\">tab</span><span class=\"tok-p\">[</span><span class=\"tok-n\">i</span><span class=\"tok-p\">]</span><span class=\"tok-p\">;</span>",
    "<span class=\"tok-w\">            </span><span class=\"tok-n\">zone</span><span class=\"tok-o\">-</span><span class=\"tok-o\">&gt;</span><span class=\"tok-n\">tab</span><span class=\"tok-p\">[</span><span class=\"tok-n\">i</span><span class=\"tok-p\">]</span><span class=\"tok-w\"> </span><span class=\"tok-o\">=</span><span class=\"tok-w\"> </span><span class=\"tok-n\">tmp</span><span class=\"tok-p\">;</span>",
