    "",
    "<span class=\"tok-w\">    </span><span class=\"tok-n\">pthread_barrier_wait</span><span class=\"tok-p\">(</span><span class=\"tok-o\">&amp;</span><span class=\"tok-n\">barrier</span><span class=\"tok-p\">)</span><span class=\"tok-p\">;</span>",
    "<span class=\"tok-w\">    </span><span class=\"tok-k\">return</span><span class=\"tok-w\"> </span><span class=\"tok-nb\">NULL</span><span class=\"tok-p\">;</span>",
    "<span class=\"tok-p\">}</span>",
    "",
    "<span class=\"tok-c1\">// checks if an array is sorted or not</span>",
    "<span class=\"tok-kt\">bool</span><span class=\"tok-w\"> </span><span class=\"tok-nf\">is_sorted</span><span class=\"tok-p\">(</span><span class=\"tok-kt\">int</span><span class=\"tok-o\">*</span><span class=\"tok-w\"> </span><span class=\"tok-n\">array</span><span class=\"tok-p\">,</span><span class=\"tok-w\"> </span><span class=\"tok-kt\">int</span><span class=\"tok-w\"> </span><span class=\"tok-n\">size</span><span class=\"tok-p\">)</span><span class=\"tok-w\"> </span><span class=\"tok-p\">{</span>",
    "<span class=\"tok-w\">    </span><span class=\"tok-k\">for</span><span class=\"tok-w\"> </span><span class=\"tok-p\">(</span><span class=\"tok-kt\">int</span><span class=\"tok-w\"> </span><span class=\"tok-n\">i</span><span class=\"tok-w\"> </span><span class=\"tok-o\">=</span><span class=\"tok-w\"> </span><span class=\"tok-mi\">0</span><span class=\"tok-p\">;</span><span class=\"tok-w\"> </span><span class=\"tok-n\">i</span><span class=\"tok-w\"> </span><span class=\"tok-o\">&lt;</span><span class=\"tok-w\"> </span><span class=\"tok-n\">size</span><span class=\"tok-mi\">-1</span><span class=\"tok-p\">;</span><span class=\"tok-w\"> </span><span class=\"tok-n\">i</span><span class=\"tok-o\">+</span><span class=\"tok-o\">+</span><span class=\"tok-p\">)</span><span class=\"tok-w\"> </span><span class=\"tok-p\">{</span>",
    "<span class=\"tok-w\">        </span><span class=\"tok-k\">if</span><span class=\"tok-w\"> </span><span class=\"tok-p\">(</span><span class=\"tok-n\">array</span><span class=\"tok-p\">[</span><span class=\"tok-n\">i</span><span class=\"tok-p\">]</span><span class=\"tok-w\"> </span><span class=\"tok-o\">&gt;</span><span class=\"tok-w\"> </span><span class=\"tok-n\">array</span><span class=\"tok-p\">[</span><span class=\"tok-n\">i</span><span class=\"tok-o\">+</span><span class=\"tok-mi\">1</span><span class=\"tok-p\">]</span><span class=\"tok-p\">)</span><span class=\"tok-p\">{</span>",
    "<span class=\"tok-w\">            </span><span class=\"tok-k\">return</span><span class=\"tok-w\"> </span><span class=\"tok-nb\">false</span><span class=\"tok-p\">;</span>",
    "<span class=\"tok-w\">        </span><span class=\"tok-p\">}</span>",
    "<span class=\"tok-w\">    </span><span class=\"tok-p\">}</span>",
