    "<span class=\"tok-k\">def</span><span class=\"tok-w\"> </span><span class=\"tok-nf\">fourier_transform</span><span class=\"tok-p\">(</span><span class=\"tok-n\">img</span><span class=\"tok-p\">:</span> <span class=\"tok-n\">np</span><span class=\"tok-o\">.</span><span class=\"tok-n\">ndarray</span><span class=\"tok-p\">)</span> <span class=\"tok-o\">-</span><span class=\"tok-o\">&gt;</span> <span class=\"tok-n\">np</span><span class=\"tok-o\">.</span><span class=\"tok-n\">ndarray</span><span class=\"tok-p\">:</span>",
    "",
    "    <span class=\"tok-n\">res</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">img</span><span class=\"tok-o\">.</span><span class=\"tok-n\">copy</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "",
    "    <span class=\"tok-n\">res_fft</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">np</span><span class=\"tok-o\">.</span><span class=\"tok-n\">fft</span><span class=\"tok-o\">.</span><span class=\"tok-n\">fft2</span><span class=\"tok-p\">(</span><span class=\"tok-n\">res</span><span class=\"tok-p\">)</span>",
    "    ",
    "    <span class=\"tok-n\">keep_fraction</span> <span class=\"tok-o\">=</span> <span class=\"tok-mf\">0.1</span>",
    "    <span class=\"tok-n\">r</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">c</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">res_fft</span><span class=\"tok-o\">.</span><span class=\"tok-n\">shape</span>",
    "",
    "    <span class=\"tok-nb\">iter</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">np</span><span class=\"tok-o\">.</span><span class=\"tok-n\">nditer</span><span class=\"tok-p\">(</span><span class=\"tok-n\">res_fft</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">flags</span><span class=\"tok-o\">=</span><span class=\"tok-p\">[</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">multi_index</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">]</span><span class=\"tok-p\">)</span>",
    "",
    "    <span class=\"tok-k\">while</span> <span class=\"tok-ow\">not</span> <span class=\"tok-nb\">iter</span><span class=\"tok-o\">.</span><span class=\"tok-n\">finished</span><span class=\"tok-p\">:</span>",
    "",
    "        <span class=\"tok-n\">i</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">j</span> <span class=\"tok-o\">=</span> <span class=\"tok-nb\">iter</span><span class=\"tok-o\">.</span><span class=\"tok-n\">multi_index</span>",
    "",
    "        <span class=\"tok-c1\"># https://scipy-lectures.org/intro/scipy/auto_examples/solutions/plot_fft_image_denoise.html</span>",
    "        <span class=\"tok-k\">if</span> <span class=\"tok-p\">(</span><span class=\"tok-p\">(</span><span class=\"tok-n\">i</span> <span class=\"tok-o\">&gt;</span><span class=\"tok-o\">=</span> <span class=\"tok-nb\">int</span><span class=\"tok-p\">(</span><span class=\"tok-n\">r</span><span class=\"tok-o\">*</span><span class=\"tok-n\">keep_fraction</span><span class=\"tok-p\">)</span> <span class=\"tok-ow\">and</span> <span class=\"tok-n\">i</span> <span class=\"tok-o\">&lt;</span> <span class=\"tok-nb\">int</span><span class=\"tok-p\">(</span><span class=\"tok-n\">r</span><span class=\"tok-o\">*</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">1</span><span class=\"tok-o\">-</span><span class=\"tok-n\">keep_fraction</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span> <span class=\"tok-ow\">or</span> ",
    "            <span class=\"tok-p\">(</span><span class=\"tok-n\">j</span> <span class=\"tok-o\">&gt;</span><span class=\"tok-o\">=</span> <span class=\"tok-nb\">int</span><span class=\"tok-p\">(</span><span class=\"tok-n\">c</span><span class=\"tok-o\">*</span><span class=\"tok-n\">keep_fraction</span><span class=\"tok-p\">)</span> <span class=\"tok-ow\">and</span> <span class=\"tok-n\">j</span> <span class=\"tok-o\">&lt;</span> <span class=\"tok-nb\">int</span><span class=\"tok-p\">(</span><span class=\"tok-n\">c</span><span class=\"tok-o\">*</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">1</span><span class=\"tok-o\">-</span><span class=\"tok-n\">keep_fraction</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
