    "    <span class=\"tok-c1\"># mirrorFreq3 = wav_to_list(&quot;./Messages/messageB_part_1.wav&quot;)</span>",
    "    <span class=\"tok-c1\"># mirrorFreq4 = wav_to_list(&quot;./Messages/messageB_part_2.wav&quot;)</span>",
