    "    <span class=\"tok-n\">cf2</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">numpy</span><span class=\"tok-o\">.</span><span class=\"tok-n\">fft</span><span class=\"tok-o\">.</span><span class=\"tok-n\">rfft</span><span class=\"tok-p\">(</span><span class=\"tok-n\">mirrorFreq2</span><span class=\"tok-p\">[</span><span class=\"tok-mi\">0</span><span class=\"tok-p\">]</span><span class=\"tok-p\">)</span>",
