    "    <span class=\"tok-n\">allsound</span><span class=\"tok-o\">.</span><span class=\"tok-n\">append</span><span class=\"tok-p\">(</span><span class=\"tok-n\">cf</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-n\">allsound</span><span class=\"tok-o\">.</span><span class=\"tok-n\">append</span><span class=\"tok-p\">(</span><span class=\"tok-n\">cf2</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-nb\">print</span><span class=\"tok-p\">(</span><span class=\"tok-n\">allsound</span><span class=\"tok-p\">)</span>",
    "",
    "    <span class=\"tok-n\">k</span> <span class=\"tok-o\">=</span> <span class=\"tok-nb\">len</span><span class=\"tok-p\">(</span><span class=\"tok-n\">cf</span><span class=\"tok-p\">)</span> <span class=\"tok-o\">/</span><span class=\"tok-o\">/</span> <span class=\"tok-mi\">2</span>",
    "    <span class=\"tok-k\">for</span> <span class=\"tok-n\">x</span> <span class=\"tok-ow\">in</span> <span class=\"tok-nb\">range</span><span class=\"tok-p\">(</span><span class=\"tok-n\">k</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "        <span class=\"tok-k\">if</span> <span class=\"tok-n\">k</span><span class=\"tok-o\">-</span><span class=\"tok-n\">x</span> <span class=\"tok-o\">&gt;</span> <span class=\"tok-mi\">0</span><span class=\"tok-p\">:</span>",
    "            <span class=\"tok-n\">tpm</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">cf</span><span class=\"tok-p\">[</span><span class=\"tok-n\">k</span><span class=\"tok-o\">-</span><span class=\"tok-n\">x</span><span class=\"tok-p\">]</span>",
    "            <span class=\"tok-n\">cf</span><span class=\"tok-p\">[</span><span class=\"tok-n\">k</span><span class=\"tok-o\">-</span><span class=\"tok-n\">x</span><span class=\"tok-p\">]</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">cf</span><span class=\"tok-p\">[</span><span class=\"tok-n\">k</span><span class=\"tok-o\">+</span><span class=\"tok-n\">x</span><span class=\"tok-p\">]</span>",
    "            <span class=\"tok-n\">cf</span><span class=\"tok-p\">[</span><span class=\"tok-n\">k</span><span class=\"tok-o\">+</span><span class=\"tok-n\">x</span><span class=\"tok-p\">]</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">tpm</span>",
    "",
    "    <span class=\"tok-n\">sound</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">numpy</span><span class=\"tok-o\">.</span><span class=\"tok-n\">fft</span><span class=\"tok-o\">.</span><span class=\"tok-n\">irfft</span><span class=\"tok-p\">(</span><span class=\"tok-n\">cf</span><span class=\"tok-p\">)</span>",
