    "",
    "",
    "<span class=\"tok-k\">def</span><span class=\"tok-w\"> </span><span class=\"tok-nf\">changement_lineaire</span><span class=\"tok-p\">(</span><span class=\"tok-n\">decalage</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "    <span class=\"tok-n\">freq1</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">wav_to_list</span><span class=\"tok-p\">(</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">./Messages/messageA_part_1.wav</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-w\">    </span><span class=\"tok-sd\">&#x27;&#x27;&#x27;</span>",
    "<span class=\"tok-sd\">    cf_lst = []</span>",
    "<span class=\"tok-sd\">    X = numpy.ndarray(decalage)</span>",
    "<span class=\"tok-sd\">    cfTranslation = numpy.fft.rfft(X)</span>",
    "<span class=\"tok-sd\">    freq1 = wav_to_list(&quot;./Messages/messageA_part_1.wav&quot;)</span>",
    "<span class=\"tok-sd\">    cf = numpy.fft.rfft(freq1[0])</span>",
    "<span class=\"tok-sd\">    for x in cf:</span>",
    "<span class=\"tok-sd\">        x += cfTranslation</span>",
    "<span class=\"tok-sd\">    sound = numpy.fft.irfft(cf)</span>",
    "<span class=\"tok-sd\">    list_to_wav(sound, &quot;shift.wav&quot;)</span>",
    "<span class=\"tok-sd\">    &#x27;&#x27;&#x27;</span>"
