    "<span class=\"tok-w\">    </span><span class=\"tok-kt\">int</span><span class=\"tok-w\"> </span><span class=\"tok-n\">socket_wait</span><span class=\"tok-w\"> </span><span class=\"tok-o\">=</span><span class=\"tok-w\"> </span><span class=\"tok-n\">socket</span><span class=\"tok-p\">(</span><span class=\"tok-n\">AF_INET</span><span class=\"tok-p\">,</span><span class=\"tok-w\"> </span><span class=\"tok-n\">SOCK_STREAM</span><span class=\"tok-p\">,</span><span class=\"tok-w\"> </span><span class=\"tok-mi\">0</span><span class=\"tok-p\">)</span><span class=\"tok-p\">;</span>",
