    "<span class=\"tok-w\">        </span><span class=\"tok-n\">die</span><span class=\"tok-p\">(</span><span class=\"tok-s\">&quot;</span><span class=\"tok-s\">listen</span><span class=\"tok-s\">&quot;</span><span class=\"tok-p\">)</span><span class=\"tok-p\">;</span>",
    "",
    "<span class=\"tok-w\">    </span><span class=\"tok-c1\">// Wait and accept connections as they come</span>",
