    "<span class=\"tok-nd\">@app</span><span class=\"tok-o\">.</span><span class=\"tok-n\">post</span><span class=\"tok-p\">(</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">/train</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">,</span><span class=\"tok-p\">)</span>",
