  {
   "type": "code",
   "caption": "BLE scanning on the Pycom board (MicroPython)",
   "lang": "py",
   "file": "bluetooth_scan_new.py",
   "lines": [
    "<span class=\"tok-kn\">from</span><span class=\"tok-w\"> </span><span class=\"tok-nn\">network</span><span class=\"tok-w\"> </span><span class=\"tok-kn\">import</span> <span class=\"tok-n\">Bluetooth</span>",
    "<span class=\"tok-kn\">from</span><span class=\"tok-w\"> </span><span class=\"tok-nn\">network</span><span class=\"tok-w\"> </span><span class=\"tok-kn\">import</span> <span class=\"tok-n\">WLAN</span>",
    "<span class=\"tok-kn\">import</span><span class=\"tok-w\"> </span><span class=\"tok-nn\">ubinascii</span>",
    "<span class=\"tok-kn\">import</span><span class=\"tok-w\"> </span><span class=\"tok-nn\">machine</span>",
    "<span class=\"tok-kn\">import</span><span class=\"tok-w\"> </span><span class=\"tok-nn\">pycom</span>",
    "<span class=\"tok-kn\">import</span><span class=\"tok-w\"> </span><span class=\"tok-nn\">time</span>",
    "",
    "<span class=\"tok-n\">expansion_board_mac</span> <span class=\"tok-o\">=</span> <span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">3c71bf875e1a</span><span class=\"tok-s2\">&quot;</span> <span class=\"tok-c1\"># Adresse MAC du expansion board</span>",
    "",
    "<span class=\"tok-n\">pycom</span><span class=\"tok-o\">.</span><span class=\"tok-n\">heartbeat</span><span class=\"tok-p\">(</span><span class=\"tok-kc\">False</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-n\">pycom</span><span class=\"tok-o\">.</span><span class=\"tok-n\">rgbled</span><span class=\"tok-p\">(</span><span class=\"tok-mh\">0x5A5A5A</span><span class=\"tok-p\">)</span>  <span class=\"tok-c1\"># White</span>",
    "<span class=\"tok-n\">time</span><span class=\"tok-o\">.</span><span class=\"tok-n\">sleep</span><span class=\"tok-p\">(</span><span class=\"tok-mf\">0.1</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-n\">wlan</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">WLAN</span><span class=\"tok-p\">(</span><span class=\"tok-n\">mode</span><span class=\"tok-o\">=</span><span class=\"tok-n\">WLAN</span><span class=\"tok-o\">.</span><span class=\"tok-n\">STA</span><span class=\"tok-p\">)</span>",
    "<span class=\"tok-n\">wlan</span><span class=\"tok-o\">.</span><span class=\"tok-n\">connect</span><span class=\"tok-p\">(</span><span class=\"tok-n\">ssid</span><span class=\"tok-o\">=</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">Pycoms</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">auth</span><span class=\"tok-o\">=</span><span class=\"tok-p\">(</span><span class=\"tok-n\">WLAN</span><span class=\"tok-o\">.</span><span class=\"tok-n\">WPA2</span><span class=\"tok-p\">,</span> <span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">max123juju456</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-k\">while</span> <span class=\"tok-ow\">not</span> <span class=\"tok-n\">wlan</span><span class=\"tok-o\">.</span><span class=\"tok-n\">isconnected</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "    <span class=\"tok-n\">machine</span><span class=\"tok-o\">.</span><span class=\"tok-n\">idle</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "<span class=\"tok-nb\">print</span><span class=\"tok-p\">(</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">WiFi connected succesfully</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">)</span>",
    "<span class=\"tok-nb\">print</span><span class=\"tok-p\">(</span><span class=\"tok-n\">wlan</span><span class=\"tok-o\">.</span><span class=\"tok-n\">ifconfig</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-n\">bt</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">Bluetooth</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-k\">if</span> <span class=\"tok-ow\">not</span> <span class=\"tok-n\">bt</span><span class=\"tok-o\">.</span><span class=\"tok-n\">isscanning</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "    <span class=\"tok-n\">bt</span><span class=\"tok-o\">.</span><span class=\"tok-n\">start_scan</span><span class=\"tok-p\">(</span><span class=\"tok-o\">-</span><span class=\"tok-mi\">1</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-k\">while</span> <span class=\"tok-n\">bt</span><span class=\"tok-o\">.</span><span class=\"tok-n\">isscanning</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "",
    "    <span class=\"tok-n\">pycom</span><span class=\"tok-o\">.</span><span class=\"tok-n\">rgbled</span><span class=\"tok-p\">(</span><span class=\"tok-mh\">0x005A00</span><span class=\"tok-p\">)</span>  <span class=\"tok-c1\"># Green</span>",
    "    <span class=\"tok-n\">time</span><span class=\"tok-o\">.</span><span class=\"tok-n\">sleep</span><span class=\"tok-p\">(</span><span class=\"tok-mf\">0.1</span><span class=\"tok-p\">)</span>",
    "",
    "    <span class=\"tok-n\">wlan</span><span class=\"tok-o\">.</span><span class=\"tok-n\">connect</span><span class=\"tok-p\">(</span><span class=\"tok-n\">ssid</span><span class=\"tok-o\">=</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">Pycoms</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">auth</span><span class=\"tok-o\">=</span><span class=\"tok-p\">(</span><span class=\"tok-n\">WLAN</span><span class=\"tok-o\">.</span><span class=\"tok-n\">WPA2</span><span class=\"tok-p\">,</span> <span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">max123juju456</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span>",
    "    <span class=\"tok-n\">time</span><span class=\"tok-o\">.</span><span class=\"tok-n\">sleep</span><span class=\"tok-p\">(</span><span class=\"tok-mf\">0.1</span><span class=\"tok-p\">)</span>",
    "",
    "    <span class=\"tok-n\">adv</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">bt</span><span class=\"tok-o\">.</span><span class=\"tok-n\">get_adv</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "",
    "    <span class=\"tok-k\">if</span> <span class=\"tok-n\">adv</span><span class=\"tok-p\">:</span>",
    "        ",
    "        <span class=\"tok-n\">adv_mac</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">ubinascii</span><span class=\"tok-o\">.</span><span class=\"tok-n\">hexlify</span><span class=\"tok-p\">(</span><span class=\"tok-n\">adv</span><span class=\"tok-o\">.</span><span class=\"tok-n\">mac</span><span class=\"tok-p\">)</span><span class=\"tok-o\">.</span><span class=\"tok-n\">decode</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "        ",
    "        <span class=\"tok-n\">pycom</span><span class=\"tok-o\">.</span><span class=\"tok-n\">rgbled</span><span class=\"tok-p\">(</span><span class=\"tok-mh\">0x005A00</span><span class=\"tok-p\">)</span>  <span class=\"tok-c1\"># Green</span>",
    "        <span class=\"tok-n\">time</span><span class=\"tok-o\">.</span><span class=\"tok-n\">sleep</span><span class=\"tok-p\">(</span><span class=\"tok-mf\">0.1</span><span class=\"tok-p\">)</span>",
    "        ",
    "        <span class=\"tok-k\">if</span>  <span class=\"tok-n\">adv_mac</span> <span class=\"tok-o\">==</span> <span class=\"tok-n\">expansion_board_mac</span><span class=\"tok-p\">:</span>",
    "            ",
    "            <span class=\"tok-n\">pycom</span><span class=\"tok-o\">.</span><span class=\"tok-n\">rgbled</span><span class=\"tok-p\">(</span><span class=\"tok-mh\">0x00005A</span><span class=\"tok-p\">)</span>  <span class=\"tok-c1\"># Blue</span>",
    "            <span class=\"tok-n\">time</span><span class=\"tok-o\">.</span><span class=\"tok-n\">sleep</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">1</span><span class=\"tok-p\">)</span>",
    ""
   ],
   "start": 2
  }
