    "<span class=\"tok-w\">        </span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">;</span>",
    "<span class=\"tok-w\">    </span><span class=\"tok-n\">trail</span><span class=\"tok-p\">.</span><span class=\"tok-n\">insert</span><span class=\"tok-p\">(</span><span class=\"tok-m\">0</span><span class=\"tok-p\">,</span><span class=\"tok-w\"> </span><span class=\"tok-n\">particleComponent</span><span class=\"tok-p\">)</span><span class=\"tok-p\">;</span>",
    "<span class=\"tok-w\">    </span><span class=\"tok-n\">gameRef</span><span class=\"tok-p\">.</span><span class=\"tok-n\">add</span><span class=\"tok-p\">(</span><span class=\"tok-n\">particleComponent</span><span class=\"tok-p\">)</span><span class=\"tok-p\">;</span>",
