    "<span class=\"tok-w\">          </span><span class=\"tok-p\">(</span><span class=\"tok-n\">position</span><span class=\"tok-p\">.</span><span class=\"tok-n\">y</span><span class=\"tok-w\"> </span><span class=\"tok-o\">+</span><span class=\"tok-w\"> </span><span class=\"tok-p\">(</span><span class=\"tok-n\">sin</span><span class=\"tok-p\">(</span><span class=\"tok-n\">angle</span><span class=\"tok-p\">)</span><span class=\"tok-w\"> </span><span class=\"tok-o\">*</span><span class=\"tok-w\"> </span><span class=\"tok-m\">2</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">.</span><span class=\"tok-n\">floor</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span><span class=\"tok-w\"> </span><span class=\"tok-o\">=</span><span class=\"tok-o\">=</span>",
    "<span class=\"tok-w\">              </span><span class=\"tok-n\">particle</span><span class=\"tok-p\">.</span><span class=\"tok-n\">position</span><span class=\"tok-p\">.</span><span class=\"tok-n\">y</span><span class=\"tok-p\">.</span><span class=\"tok-n\">floor</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-w\"> </span><span class=\"tok-p\">{</span>",
    "<span class=\"tok-w\">        </span><span class=\"tok-n\">destroyPlayer</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span><span class=\"tok-p\">;</span>",
