    "<span class=\"tok-c1\"># Get the number of rows and columns in the data set</span>",
    "<span class=\"tok-n\">df</span><span class=\"tok-o\">.</span><span class=\"tok-n\">shape</span>",
    "",
    "<span class=\"tok-c1\"># Visualize the closing price history</span>",
    "<span class=\"tok-n\">plt</span><span class=\"tok-o\">.</span><span class=\"tok-n\">figure</span><span class=\"tok-p\">(</span><span class=\"tok-n\">figsize</span><span class=\"tok-o\">=</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">16</span><span class=\"tok-p\">,</span><span class=\"tok-mi\">8</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span>",
