    "<span class=\"tok-c1\"># Convert the dataframe to a numpy array</span>",
    "<span class=\"tok-n\">dataset</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">data</span><span class=\"tok-o\">.</span><span class=\"tok-n\">values</span>",
    "<span class=\"tok-c1\"># Get the number of rows to train the model one</span>",
    "<span class=\"tok-n\">training_data_len</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">math</span><span class=\"tok-o\">.</span><span class=\"tok-n\">ceil</span><span class=\"tok-p\">(</span><span class=\"tok-nb\">len</span><span class=\"tok-p\">(</span><span class=\"tok-n\">dataset</span><span class=\"tok-p\">)</span> <span class=\"tok-o\">*</span> <span class=\"tok-mf\">.8</span><span class=\"tok-p\">)</span>",
