    "<span class=\"tok-n\">scaled_data</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">scaler</span><span class=\"tok-o\">.</span><span class=\"tok-n\">fit_transform</span><span class=\"tok-p\">(</span><span class=\"tok-n\">dataset</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-n\">scaled_data</span>",
    "",
    "<span class=\"tok-c1\"># Create the training data set</span>",
    "<span class=\"tok-c1\"># Create the scaled training data set</span>",
    "<span class=\"tok-n\">train_data</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">scaled_data</span><span class=\"tok-p\">[</span><span class=\"tok-mi\">0</span><span class=\"tok-p\">:</span><span class=\"tok-n\">training_data_len</span><span class=\"tok-p\">,</span> <span class=\"tok-p\">:</span><span class=\"tok-p\">]</span>",
    "<span class=\"tok-c1\"># Split the data into x_train and y_train data sets</span>",
    "<span class=\"tok-n\">x_train</span> <span class=\"tok-o\">=</span> <span class=\"tok-p\">[</span><span class=\"tok-p\">]</span> <span class=\"tok-c1\"># Independant training variables/features</span>",
    "<span class=\"tok-n\">y_train</span> <span class=\"tok-o\">=</span> <span class=\"tok-p\">[</span><span class=\"tok-p\">]</span> <span class=\"tok-c1\"># Dependant variables or target variables</span>",
    "",
    "<span class=\"tok-k\">for</span> <span class=\"tok-n\">i</span> <span class=\"tok-ow\">in</span> <span class=\"tok-nb\">range</span><span class=\"tok-p\">(</span><span class=\"tok-mi\">60</span><span class=\"tok-p\">,</span> <span class=\"tok-nb\">len</span><span class=\"tok-p\">(</span><span class=\"tok-n\">train_data</span><span class=\"tok-p\">)</span><span class=\"tok-p\">)</span><span class=\"tok-p\">:</span>",
    "  <span class=\"tok-n\">x_train</span><span class=\"tok-o\">.</span><span class=\"tok-n\">append</span><span class=\"tok-p\">(</span><span class=\"tok-n\">train_data</span><span class=\"tok-p\">[</span><span class=\"tok-n\">i</span><span class=\"tok-o\">-</span><span class=\"tok-mi\">60</span><span class=\"tok-p\">:</span><span class=\"tok-n\">i</span><span class=\"tok-p\">,</span> <span class=\"tok-mi\">0</span><span class=\"tok-p\">]</span><span class=\"tok-p\">)</span> <span class=\"tok-c1\"># x_train will contain 60 values which will be indexed from position 0 to 59</span>",
    "  <span class=\"tok-n\">y_train</span><span class=\"tok-o\">.</span><span class=\"tok-n\">append</span><span class=\"tok-p\">(</span><span class=\"tok-n\">train_data</span><span class=\"tok-p\">[</span><span class=\"tok-n\">i</span><span class=\"tok-p\">,</span> <span class=\"tok-mi\">0</span><span class=\"tok-p\">]</span><span class=\"tok-p\">)</span> <span class=\"tok-c1\"># y_train will contain the 60 first values which will be at position 60</span>",
