    "<span class=\"tok-c1\"># Split our training data, for creating our model</span>",
    "<span class=\"tok-c1\"># Split 1: 80% for training and 20% for testing the accuracy</span>",
    "<span class=\"tok-c1\"># Select features</span>",
    "<span class=\"tok-n\">X</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">df_train_final</span>",
