    "<span class=\"tok-n\">tf_idf_table</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">tf_idf_table</span><span class=\"tok-o\">.</span><span class=\"tok-n\">drop</span><span class=\"tok-p\">(</span><span class=\"tok-n\">columns</span> <span class=\"tok-o\">=</span> <span class=\"tok-p\">[</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">target</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">]</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-n\">df_train_final_merged</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">pd</span><span class=\"tok-o\">.</span><span class=\"tok-n\">concat</span><span class=\"tok-p\">(</span><span class=\"tok-p\">[</span><span class=\"tok-n\">X_train</span><span class=\"tok-o\">.</span><span class=\"tok-n\">reset_index</span><span class=\"tok-p\">(</span><span class=\"tok-n\">drop</span><span class=\"tok-o\">=</span><span class=\"tok-kc\">True</span><span class=\"tok-p\">)</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">tf_idf_table</span><span class=\"tok-o\">.</span><span class=\"tok-n\">reset_index</span><span class=\"tok-p\">(</span><span class=\"tok-n\">drop</span><span class=\"tok-o\">=</span><span class=\"tok-kc\">True</span><span class=\"tok-p\">)</span><span class=\"tok-p\">]</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">axis</span><span class=\"tok-o\">=</span><span class=\"tok-mi\">1</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-c1\"># Assign column names</span>",
    "<span class=\"tok-n\">column_names</span> <span class=\"tok-o\">=</span> <span class=\"tok-nb\">list</span><span class=\"tok-p\">(</span><span class=\"tok-n\">X_train</span><span class=\"tok-o\">.</span><span class=\"tok-n\">columns</span><span class=\"tok-p\">)</span> <span class=\"tok-o\">+</span> <span class=\"tok-nb\">list</span><span class=\"tok-p\">(</span><span class=\"tok-n\">tf_idf_table</span><span class=\"tok-o\">.</span><span class=\"tok-n\">columns</span><span class=\"tok-p\">)</span>",
    "<span class=\"tok-n\">df_train_final_merged</span><span class=\"tok-o\">.</span><span class=\"tok-n\">columns</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">column_names</span>",
    "",
    "<span class=\"tok-n\">df_train_final_merged</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">df_train_final_merged</span><span class=\"tok-o\">.</span><span class=\"tok-n\">dropna</span><span class=\"tok-p\">(</span><span class=\"tok-p\">)</span>",
    "",
    "<span class=\"tok-n\">X_train</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">df_train_final_merged</span><span class=\"tok-o\">.</span><span class=\"tok-n\">drop</span><span class=\"tok-p\">(</span><span class=\"tok-n\">columns</span> <span class=\"tok-o\">=</span> <span class=\"tok-p\">[</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">participant_id</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">,</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">target</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">,</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">target_icar</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">,</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">text</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">]</span><span class=\"tok-p\">)</span>",
    "<span class=\"tok-n\">y_train</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">df_train_final_merged</span><span class=\"tok-p\">[</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">target</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">]</span>",
    "",
    "<span class=\"tok-c1\"># 1. Set up our model</span>",
    "<span class=\"tok-n\">model</span> <span class=\"tok-o\">=</span> <span class=\"tok-n\">LogisticRegression</span><span class=\"tok-p\">(</span><span class=\"tok-n\">penalty</span><span class=\"tok-o\">=</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">l2</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">solver</span><span class=\"tok-o\">=</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-s1\">lbfgs</span><span class=\"tok-s1\">&#x27;</span><span class=\"tok-p\">,</span> <span class=\"tok-n\">max_iter</span><span class=\"tok-o\">=</span><span class=\"tok-mi\">1000</span><span class=\"tok-p\">)</span>",
