    "",
    "<span class=\"tok-w\">                </span><span class=\"tok-n\">commands</span><span class=\"tok-p\">.</span><span class=\"tok-n\">trigger</span><span class=\"tok-p\">(</span><span class=\"tok-n\">DamageEvent</span><span class=\"tok-w\"> </span><span class=\"tok-p\">{</span>",
