    "                <span class=\"tok-n\">aliases</span><span class=\"tok-o\">=</span><span class=\"tok-p\">[</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">BTC</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">,</span> <span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">bitcoin value</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">,</span> <span class=\"tok-s2\">&quot;</span><span class=\"tok-s2\">bitcoin price</span><span class=\"tok-s2\">&quot;</span><span class=\"tok-p\">]</span><span class=\"tok-p\">,</span>",
